(* [comment removed for export] *)
Definition req_seg2_stmt : Prop :=
  forall (s : as_St H) (LB : list block) (LF : list fframe) (pt : bptr)
    pcv rax sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s2x (ra s0v s1v s2v s3v s4v s5v s6v : word) s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P verb MP TP At ver lo shi : Z) (mbs tbs : list byte) (h : hdrv) (junk : list byte),
  (pcv = Z_to_bv 64 ART_RET1 \/ pcv = ret_pc (Z_to_bv 64 ART_RET1)) ->
  req_frames m sp ra s0v s1v s2v s3v s4v s5v s6v TP (Z.of_nat (length tbs)) P MP (Z.of_nat (length mbs)) ver AWK_RET_RT ->
  rw_cells asegs m (P + O_PR_HDR) (HdrCells h) -> hdr_empty h ->
  rw_cells asegs m At [CB (Z.to_nat (Z.of_nat (length tbs) + 1)) junk] ->
  In (pt, At, Z.of_nat (length tbs) + 1) LB -> addressable m At (Z.of_nat (length tbs) + 1) ->
  bytes_at asegs m MP mbs -> bytes_at asegs m TP tbs ->
  (TP + Z.of_nat (length tbs) <= At \/ At + (Z.of_nat (length tbs) + 1) <= TP) ->
  (MP + Z.of_nat (length mbs) <= At \/ At + (Z.of_nat (length tbs) + 1) <= MP) ->
  (P + 256 <= At \/ At + (Z.of_nat (length tbs) + 1) <= P) ->
  (MP + Z.of_nat (length mbs) <= P \/ P + 256 <= MP) -> (TP + Z.of_nat (length tbs) <= P \/ P + 256 <= TP) ->
  stk asegs m lo (bv_unsigned sp + -144) ->
  req_pure sp P MP TP lo mbs tbs -> 0 <= verb < 2^32 -> verb = verb_of (zbytes mbs) -> (ver = 10 \/ ver = 11) -> mem_inv asegs m ->
  bv_unsigned ra mod 2 = 0 ->
  (* [comment removed for export] *)
  tp = Z_to_bv 64 ATP -> ACONST m -> as_RHEAP H s LB m -> as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp <= shi ->
  0 <= P -> aobj LB LF P 256 -> accessible m P 256 ->
  aobj LB LF MP (Z.of_nat (length mbs)) -> accessible m MP (Z.of_nat (length mbs)) ->
